import Link from "next/link";
import { site } from "@/config/site";
import { cn } from "@/lib/utils";

/*
 * The Bidfolio mark: a folio sheet whose top-left corner is folded over; the gap between the
 * folded flap and the sheet is a tick. One colour (currentColor).
 * Path data is generated by scripts/design/logo-geometry.mjs — tune it there.
 */
export const MARK_24 =
  "M15.375 1H18.5a1.5 1.5 0 0 1 1.5 1.5V21.5a1.5 1.5 0 0 1-1.5 1.5H5.5a1.5 1.5 0 0 1-1.5-1.5V7.375L8.22 10.54ZM5.1 5.45L7.78 7.46 11.8 2.1Z";
/** Drawn on a 16 px grid with whole-pixel edges and a wider tick, for sizes below 20 px. */
export const MARK_16 =
  "M11.563 1H12a1 1 0 0 1 1 1V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5.813L6.17 8.19ZM3.85 4.325L5.83 5.81 8.8 1.85Z";

/** The mark on its own. Decorative by default; pass `title` when it stands alone as a link or image. */
export function LogoMark({ size = 24, title, className }: { size?: number; title?: string; className?: string }) {
  const small = size < 20;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={small ? "0 0 16 16" : "0 0 24 24"}
      width={size}
      height={size}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={cn("shrink-0 text-brand", className)}
    >
      <path d={small ? MARK_16 : MARK_24} />
    </svg>
  );
}

const sizes = {
  sm: { mark: 20, text: "text-lg leading-6" },
  md: { mark: 24, text: "text-xl leading-7" },
  lg: { mark: 32, text: "text-2xl leading-8" },
} as const;

/** The wordmark in the display serif, sentence case. Not a link. */
export function Wordmark({
  size = "md",
  tone = "default",
  className,
}: {
  size?: keyof typeof sizes;
  tone?: "default" | "inverse";
  className?: string;
}) {
  return (
    <span className={cn("inline-flex items-center gap-2", className)}>
      <LogoMark size={sizes[size].mark} className={tone === "inverse" ? "text-paper" : undefined} />
      <span className={cn("font-display font-semibold tracking-[-0.01em]", sizes[size].text, tone === "inverse" ? "text-paper" : "text-ink")}>{site.name}</span>
    </span>
  );
}

/** Horizontal lockup (mark + wordmark) linking home. The link's accessible name is the product name. */
export function Logo({
  href = "/",
  size = "md",
  tone = "default",
  className,
}: {
  href?: string;
  size?: keyof typeof sizes;
  tone?: "default" | "inverse";
  className?: string;
}) {
  return (
    <Link href={href} className={cn("inline-flex items-center rounded-sm", className)}>
      <Wordmark size={size} tone={tone} />
    </Link>
  );
}
